<?php
require __DIR__ . '/../config/auth.php';requireLogin();require_once __DIR__ . '/../config/db.php';require __DIR__ . '/../config/layout.php';require_once __DIR__ . '/../config/mejoras.php';verify_csrf();
$sectores=sectoresEditables($pdo);$ids=array_map(fn($s)=>(int)$s['id'],$sectores);
if(!esAdmin()&&!$ids){http_response_code(403);exit('No tenés permiso para gestionar la papelera.');}
$msg=$_SESSION['papelera_msg']??'';unset($_SESSION['papelera_msg']);$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['accion']??'')!=='restaurar')throw new RuntimeException('Acción no válida.');restaurarPapelera($pdo,(int)($_POST['id']??0));$_SESSION['papelera_msg']='Elemento restaurado. Si su carpeta original sigue en papelera, se recupera en la raíz del sector.';header('Location: '.app_url('/php/admin/papelera.php'));exit;}catch(Throwable $e){if($e instanceof PDOException)error_log('[NASER] restaurar papelera: '.$e->getMessage());$err=$e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'No se pudo restaurar el elemento. Intentá nuevamente.';}}
$sid=(int)($_GET['sector_id']??0);if(!in_array($sid,$ids,true))$sid=0;$estado=($_GET['estado']??'')==='restaurados'?'restaurados':'pendientes';
$where=[esAdmin()?'1=1':($ids?'p.sector_id IN ('.implode(',',$ids).')':'0')];$params=[];if($sid){$where[]='p.sector_id=?';$params[]=$sid;}$where[]=$estado==='restaurados'?'p.restaurado_en IS NOT NULL':'p.restaurado_en IS NULL';
$sqlWhere=implode(' AND ',$where);$st=$pdo->prepare('SELECT COUNT(*) FROM papelera p WHERE '.$sqlWhere);$st->execute($params);$total=(int)$st->fetchColumn();$paginas=max(1,(int)ceil($total/40));$pagina=min($paginas,max(1,(int)($_GET['pagina']??1)));$offset=($pagina-1)*40;
$st=$pdo->prepare("SELECT p.*,u.nombre usuario,s.nombre sector FROM papelera p LEFT JOIN usuarios u ON u.id=p.usuario_id LEFT JOIN sectores s ON s.id=p.sector_id WHERE $sqlWhere ORDER BY p.id DESC LIMIT 40 OFFSET $offset");$st->execute($params);$rows=$st->fetchAll();$tipos=['documento'=>'Documento','carpeta'=>'Carpeta y contenido','formulario'=>'Formulario'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Papelera | NASER</title><link rel="stylesheet" href="<?=asset('/style.css')?>"><link rel="stylesheet" href="<?=asset('/css/mejoras.css')?>"></head><body><div class="app"><?php sidebar($pdo,'papelera');?><main class="content">
<header class="section-top"><div><p class="eyebrow">RECUPERACIÓN</p><h1>Papelera</h1><p>Recuperá formularios, documentos y carpetas eliminados. Sus archivos se conservan para poder restaurarlos.</p></div><a class="btn secondary" href="<?=app_url('/php/admin/auditoria.php')?>">Historial de cambios</a></header>
<?php if($msg):?><div class="alert success" role="status"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert error" role="alert"><?=h($err)?></div><?php endif;?>
<form method="get" class="mej-filters form-panel"><label>Sector<select name="sector_id"><option value="">Todos los habilitados</option><?php foreach($sectores as $s):?><option value="<?=(int)$s['id']?>" <?=$sid===(int)$s['id']?'selected':''?>><?=h($s['nombre'])?></option><?php endforeach;?></select></label><label>Estado<select name="estado"><option value="pendientes" <?=$estado==='pendientes'?'selected':''?>>Por recuperar</option><option value="restaurados" <?=$estado==='restaurados'?'selected':''?>>Ya recuperados</option></select></label><button class="btn primary">Filtrar</button></form>
<section class="table-panel"><div class="section-head"><h2><?=$estado==='pendientes'?'Elementos por recuperar':'Elementos recuperados'?></h2><span class="count-pill"><?=$total?></span></div><div class="table-wrap"><table><thead><tr><th>Elemento</th><th>Sector</th><th>Eliminado por</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><strong><?=h($r['nombre'])?></strong><small><?=h($tipos[$r['tipo']]??$r['tipo'])?> · #<?=(int)$r['registro_id']?></small></td><td><?=h($r['sector']??'Sector')?></td><td><?=h($r['usuario']??'Sistema')?></td><td><?=h($r['creado_en'])?></td><td><?php if(!$r['restaurado_en']):?><form method="post"><?=csrf_field()?><input type="hidden" name="accion" value="restaurar"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn secondary">Restaurar</button></form><?php else:?><small>Recuperado el <?=h($r['restaurado_en'])?></small><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No hay elementos en esta vista.</td></tr><?php endif;?></tbody></table></div></section>
<nav class="mej-pagination" aria-label="Páginas de la papelera"><?php if($pagina>1):?><a class="btn secondary" href="<?=h(app_url('/php/admin/papelera.php').'?'.http_build_query(['sector_id'=>$sid,'estado'=>$estado,'pagina'=>$pagina-1]))?>">← Anterior</a><?php endif;?><span>Página <?=$pagina?> de <?=$paginas?></span><?php if($pagina<$paginas):?><a class="btn secondary" href="<?=h(app_url('/php/admin/papelera.php').'?'.http_build_query(['sector_id'=>$sid,'estado'=>$estado,'pagina'=>$pagina+1]))?>">Siguiente →</a><?php endif;?></nav></main></div></body></html>
